; =====================================================================
; I2C master Z80 for the PC-1600, speed lab, V2: V1 with the send loop unrolled
; Generated by tools/make_lab.py from asm/i2c_z80_v1.0.asm (main code) with fixed entry points.
; Principle, pins and rules: see i2c_z80_v1.0.asm (SDA = page of the code + I register, A8 = pin 31).
; Entry points: WH &C100  RH &C120  STH &C1F5 | STT &C200  WL &C210  SL &C220  STL &C2F5
; =====================================================================

HV      EQU 0C1h        ; I for the pages with A8 = 1 (SDA released)
LV      EQU 0C2h        ; I for the pages with A8 = 0 (SDA low)
OPC     EQU 18h         ; port: bit 7 -> SDO (pin 29, SCL), bit 6 -> buzzer (keep 0)
DDB     EQU 1Dh         ; port B direction (bit 2 = PB2 must be an input)
PBP     EQU 1Fh         ; port B data (bit 2 = SDA read back)

S_H1    EQU 81h         ; SCL = 1, A register bit 0 = 1 (A8 = 1)
S_L1    EQU 01h         ; SCL = 0, A8 = 1
S_H0    EQU 80h         ; SCL = 1, A8 = 0
S_L0    EQU 00h         ; SCL = 0, A8 = 0

RX      EQU 0C600h
TX      EQU 0C700h
CNT     EQU 0C5FBh
IA      EQU 0C5FCh
IW      EQU 0C5FDh
IR      EQU 0C5FEh
IS      EQU 0C5FFh

        ORG 0C100h
WH:     LD A,S_H1
        OUT (OPC),A
        IN A,(PBP)
        LD D,A
        LD A,S_L1
        OUT (OPC),A
        RET
        ORG 0C120h
RH:     LD A,S_H1
        OUT (OPC),A
        IN A,(PBP)
        RRA             ; bit 2 -> carry
        RRA
        RRA
        LD A,S_L1       ; LD and OUT do not change the carry
        OUT (OPC),A
        RL E
        DJNZ RH
        RET
        ORG 0C140h
SH7:    BIT 7,C
        JP Z,TL7
SH7C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
SH6:    BIT 6,C
        JP Z,TL6
SH6C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
SH5:    BIT 5,C
        JP Z,TL5
SH5C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
SH4:    BIT 4,C
        JP Z,TL4
SH4C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
SH3:    BIT 3,C
        JP Z,TL3
SH3C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
SH2:    BIT 2,C
        JP Z,TL2
SH2C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
SH1:    BIT 1,C
        JP Z,TL1
SH1C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
SH0:    BIT 0,C
        JP Z,TL0
SH0C:   LD A,S_H1
        OUT (OPC),A
        LD A,S_L1
        OUT (OPC),A
        JP WH
TL7:    LD A,LV
        LD I,A
        JP SL7C
TL6:    LD A,LV
        LD I,A
        JP SL6C
TL5:    LD A,LV
        LD I,A
        JP SL5C
TL4:    LD A,LV
        LD I,A
        JP SL4C
TL3:    LD A,LV
        LD I,A
        JP SL3C
TL2:    LD A,LV
        LD I,A
        JP SL2C
TL1:    LD A,LV
        LD I,A
        JP SL1C
TL0:    LD A,LV
        LD I,A
        JP SL0C
        ORG 0C1F5h
STH:    LD A,S_H1
        OUT (OPC),A
        NOP
        NOP
        NOP
        LD A,LV
        LD I,A
        ORG 0C200h
STT:    NOP
        NOP
        LD A,S_L0
        OUT (OPC),A
        RET
        ORG 0C210h
WL:     LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        RET
        ORG 0C220h
SL:     BIT 7,C
        JP NZ,TH7
SL7C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        BIT 6,C
        JP NZ,TH6
SL6C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        BIT 5,C
        JP NZ,TH5
SL5C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        BIT 4,C
        JP NZ,TH4
SL4C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        BIT 3,C
        JP NZ,TH3
SL3C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        BIT 2,C
        JP NZ,TH2
SL2C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        BIT 1,C
        JP NZ,TH1
SL1C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        BIT 0,C
        JP NZ,TH0
SL0C:   LD A,S_H0
        OUT (OPC),A
        LD A,S_L0
        OUT (OPC),A
        LD A,HV
        LD I,A
        JP WH
TH7:    LD A,HV
        LD I,A
        JP SH7C
TH6:    LD A,HV
        LD I,A
        JP SH6C
TH5:    LD A,HV
        LD I,A
        JP SH5C
TH4:    LD A,HV
        LD I,A
        JP SH4C
TH3:    LD A,HV
        LD I,A
        JP SH3C
TH2:    LD A,HV
        LD I,A
        JP SH2C
TH1:    LD A,HV
        LD I,A
        JP SH1C
TH0:    LD A,HV
        LD I,A
        JP SH0C
        ORG 0C2F5h
STL:    LD A,S_H0
        OUT (OPC),A
        NOP
        NOP
        NOP
        LD A,HV
        LD I,A
        ORG 0C300h
STP2:   NOP
        NOP
        NOP
        LD A,S_L1
        OUT (OPC),A
        RET

        ORG 0C400h
IC:     LD A,S_L1
        OUT (OPC),A             ; SCL low at once: from here on A8 may chop
        LD A,I
        PUSH AF                 ; I and IFF2 (P/V flag)
        DI
        IN A,(DDB)
        AND 0FBh
        OUT (DDB),A             ; PB2 = input
        XOR A
        LD (IS),A
        CALL BUSCHK
        JP C,E3
        LD A,(IW)
        OR A
        JR NZ,DOWR
        LD A,(IR)
        OR A
        JR NZ,DORD              ; W = 0, R > 0: read at once
DOWR:   CALL START
        LD A,(IA)
        ADD A,A
        LD C,A                  ; address, write bit = 0
        CALL SENDB
        BIT 2,D
        JP NZ,E1                ; no ACK
        LD A,(IW)
        OR A
        JR Z,AFTW
        LD (CNT),A
        LD HL,TX
WLP:    LD C,(HL)
        INC HL
        CALL SENDB
        BIT 2,D
        JP NZ,E2
        LD A,(CNT)
        DEC A
        LD (CNT),A
        JR NZ,WLP
AFTW:   LD A,(IR)
        OR A
        JR Z,DOSTOP
DORD:   CALL START              ; (repeated) START
        LD A,(IA)
        ADD A,A
        INC A
        LD C,A                  ; address, read bit = 1
        CALL SENDB
        BIT 2,D
        JP NZ,E1
        LD A,(IR)
        LD (CNT),A
        LD HL,RX
RLP:    CALL RECVB
        LD (HL),E
        INC HL
        LD A,(CNT)
        DEC A
        LD (CNT),A
        JR Z,RLAST
        LD A,LV
        LD I,A
        CALL WL                 ; ACK
        JR RLP
RLAST:  LD A,HV
        LD I,A
        CALL WH                 ; NACK after the last byte
DOSTOP: CALL STOP
EXIT:   POP AF
        LD I,A                  ; I restored (flags are not changed)
        JP PO,EX2               ; P/V = IFF2: interrupts were off
        EI
EX2:    LD A,(IS)
        LD E,A
        LD D,0
        SCF                     ; CALL IC,E returns the result in E
        RET
E1:     LD A,1
        JR ERR
E2:     LD A,2
ERR:    LD (IS),A
        CALL STOP
        JR EXIT
E3:     LD A,3
        LD (IS),A
        JR EXIT

BUSCHK: LD A,HV                 ; up to 10 clocks until SDA is high
        LD I,A
        LD B,10
BC1:    CALL WH
        BIT 2,D
        JR NZ,BCOK
        DJNZ BC1
        SCF                     ; SDA stuck low
        RET
BCOK:   OR A
        RET

START:  LD A,HV
        LD I,A
        JP STH
STOP:   LD A,LV
        LD I,A
        JP STL
SENDB:  LD A,LV                 ; send the byte in C, then read the ACK bit into D
        LD I,A
        LD B,8
        JP SL
RECVB:  LD A,HV                 ; read a byte into E
        LD I,A
        LD B,8
        JP RH

; ---------------------------------------------------------------------
; port benchmark: 2560 port accesses per call (BASIC times the calls with TIME)
; ---------------------------------------------------------------------
        ORG 0C500h
BO:     DI                      ; (the first byte, 243, marks the lab version)
        LD A,S_L1
        LD B,0
BO1:
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        OUT (OPC),A
        DJNZ BO1
        EI
        RET
        ORG 0C520h
BI:     DI
        LD B,0
BI1:
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        IN A,(PBP)
        DJNZ BI1
        EI
        RET
        ORG 0C540h
BN:     DI
        LD B,0
BN1:
        NOP
        NOP
        NOP
        NOP
        NOP
        NOP
        NOP
        NOP
        NOP
        NOP
        DJNZ BN1
        EI
        RET
